mapper.select:
SELECT o.id, o.session_id, o.member_id, o.product_id, o.quantity, o.amount, o.operator_id, o.create_time, p.name AS product_name, m.name AS member_name FROM product_order o LEFT JOIN product p ON p.id = o.product_id LEFT JOIN member m ON m.id = o.member_id
AND o.member_id = #{memberId} AND o.session_id = #{sessionId}
ORDER BY o.create_time DESC
